1	/**
2	 * Shared-hosting primitives (Phase 1 foundation).
3	 *
4	 * Pure, framework-free helpers the account lifecycle is built on — unit-tested so
5	 * the parts that end up in a shell command on a MULTI-TENANT box (a username, a
6	 * quota, a domain in an nginx `server_name`) are provably well-formed before they
7	 * ever get there. On a shared box a single bad interpolation is not one
8	 * customer's bug, it is everyone's; these validators are the first line of that.
9	 */
10	
11	/** A syntactically valid domain for a name-based vhost (no scheme, no path). */
12	const DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
13	
14	/** True for a hostname safe to place in an nginx `server_name` / a cert request. */
15	export function isValidHostingDomain(domain: string): boolean {
16	  const d = String(domain ?? "").trim().toLowerCase().replace(/\.$/, "");
17	  return DOMAIN_RE.test(d);
18	}
19	
20	export function normalizeHostingDomain(domain: string): string {
21	  return String(domain ?? "").trim().toLowerCase().replace(/^www\./, "").replace(/\.$/, "");
22	}
23	
24	/**
25	 * Canonical form of a hostname for the HostingHostnameClaim registry: trimmed,
26	 * lowercased, trailing dot stripped. Applied on BOTH the claim insert and every
27	 * lookup/free, so a case/format variant can never dodge the UNIQUE(hostname).
28	 * Deliberately does NOT strip a leading `www.` (unlike normalizeHostingDomain) —
29	 * a claim reserves the exact nginx `server_name` that will be served.
30	 */
31	export function normalizeClaimHostname(name: string): string {
32	  return String(name ?? "").trim().toLowerCase().replace(/\.$/, "");
33	}
34	
35	/**
36	 * A safe jailed Linux username for an account, derived deterministically and kept
37	 * short (Linux caps usernames at 32 chars; some tooling chokes past 16). Starts
38	 * with a letter, lowercase alnum only — nothing a shell could ever interpret.
39	 *
40	 * `seed` (email localpart or account id) proposes a readable base; `disambiguator`
41	 * (a slice of the account id) guarantees per-node uniqueness without a DB probe.
42	 * The result still has to pass `isValidUnixUsername` before use, and the caller
43	 * resolves any residual collision against the DB (`@@unique([hostingNodeId, username])`).
44	 */
45	export function deriveUsername(seed: string, disambiguator: string): string {
46	  const base = String(seed ?? "")
47	    .toLowerCase()
48	    .replace(/[^a-z0-9]/g, "")
49	    .replace(/^[0-9]+/, "") // must not start with a digit
50	    .slice(0, 8);
51	  const suffix = String(disambiguator ?? "")
52	    .toLowerCase()
53	    .replace(/[^a-z0-9]/g, "")
54	    .slice(0, 6);
55	  // Guarantee a non-empty body so the result always clears the min-length rule
56	  // even when both inputs sanitise away to nothing.
57	  const body = `${base}${suffix}` || "acct";
58	  return `nx${body}`.slice(0, 16);
59	}
60	
61	const UNIX_USER_RE = /^[a-z][a-z0-9]{2,31}$/;
62	
63	/** True only for a shell-inert, policy-valid Linux username. */
64	export function isValidUnixUsername(name: string): boolean {
65	  return UNIX_USER_RE.test(String(name ?? ""));
66	}
67	
68	/**
69	 * Base zone for the FREE temporary hosting subdomain a customer can start on
70	 * before they connect a real domain (`<username>.nxeon.cloud`). Env-overridable so
71	 * a different install can point it at its own wildcard zone. The customer's account
72	 * `username` is already a shell-inert, per-node-unique slug (deriveUsername), so
73	 * `<username>.<base>` is a valid, collision-safe hostname claimed with kind PRIMARY
74	 * exactly like a real domain — the hostname-uniqueness guard is identical.
75	 */
76	export const HOSTING_SUBDOMAIN_BASE = process.env.HOSTING_SUBDOMAIN_BASE || "sites.nxeon.cloud";
77	
78	/** The free temporary subdomain for an account username, e.g. `nxjane.sites.nxeon.cloud`. */
79	export function tempSubdomainFor(username: string): string {
80	  return `${username}.${HOSTING_SUBDOMAIN_BASE}`;
81	}
82	
83	/**
84	 * The free subdomain for a customer-chosen label, e.g. `mysite.sites.nxeon.cloud`.
85	 * The label is validated (isValidSubdomainLabel) and de-duplicated by the same
86	 * atomic UNIQUE(hostname) claim a real domain gets — see orderHostingAccount.
87	 */
88	export function freeSubdomainFor(label: string): string {
89	  return `${String(label ?? "").trim().toLowerCase()}.${HOSTING_SUBDOMAIN_BASE}`;
90	}
91	
92	/**
93	 * True when a hostname is one of OUR free wildcard subdomains (the account's
94	 * website lives at `<label>.<HOSTING_SUBDOMAIN_BASE>`). These resolve automatically
95	 * via the `*.<base>` wildcard A record, so the customer never has to point DNS or
96	 * add an A record — the portal shows "live" instead of the point-your-domain flow.
97	 */
98	export function isFreeSubdomain(host: string): boolean {
99	  const h = String(host ?? "").trim().toLowerCase().replace(/\.$/, "");
100	  return h === HOSTING_SUBDOMAIN_BASE || h.endsWith(`.${HOSTING_SUBDOMAIN_BASE}`);
101	}
102	
103	/**
104	 * Opt-in flag for the ONE wildcard TLS cert (`*.<HOSTING_SUBDOMAIN_BASE>`) that
105	 * gives every free-subdomain site INSTANT trusted HTTPS off a single Let's Encrypt
106	 * lineage — instead of a per-subdomain HTTP-01 cert (slow AND capped at ~50
107	 * certs/week per registered domain, a hard wall at ad scale). Read at call time so
108	 * the whole wildcard path is pure opt-in: when it is not `"1"` every code path
109	 * behaves EXACTLY as before (self-signed fallback + per-domain sweep).
110	 */
111	export function hostingWildcardEnabled(): boolean {
112	  return process.env.HOSTING_WILDCARD_SSL === "1";
113	}
114	
115	/**
116	 * The certbot `live` dir for the wildcard cert. `--cert-name <base>` pins the
117	 * lineage to the base zone, so its fullchain/privkey land here — the dir the free-
118	 * subdomain vhosts point their `ssl_certificate` at when the wildcard is enabled.
119	 */
120	export function wildcardCertLiveDir(): string {
121	  return `/etc/letsencrypt/live/${HOSTING_SUBDOMAIN_BASE}`;
122	}
123	
124	/**
125	 * True when the single-label wildcard cert `*.<HOSTING_SUBDOMAIN_BASE>` ACTUALLY
126	 * covers `host` — i.e. `host` is exactly one DNS label under the base
127	 * (`foo.sites.nxeon.cloud`). It deliberately rejects the bare base and any
128	 * two-label name (`a.b.sites.nxeon.cloud`): a single-label wildcard never matches
129	 * those, and they don't resolve via the `*.<base>` A record either, so serving the
130	 * wildcard cert for them would be a name MISMATCH. This is the precise "the
131	 * wildcard serves this exact name" test the vhost wiring uses — stricter than
132	 * isFreeSubdomain (which also matches the base + deeper names) on purpose.
133	 */
134	export function wildcardCoversHost(host: string): boolean {
135	  const h = String(host ?? "").trim().toLowerCase().replace(/\.$/, "");
136	  const suffix = `.${HOSTING_SUBDOMAIN_BASE}`;
137	  if (!h.endsWith(suffix)) return false;
138	  const left = h.slice(0, h.length - suffix.length);
139	  return left.length > 0 && !left.includes(".");
140	}
141	
142	export type HostingPlanLimits = {
143	  diskGB: number;
144	  maxSites: number;
145	  maxDatabases: number;
146	  bandwidthTB: number;
147	  phpVersions: string[];
148	};
149	
150	/** The effective, sanitised limits for an account, snapshotted from its plan. */
151	export function planLimits(plan: {
152	  diskGB: number;
153	  maxSites: number;
154	  maxDatabases: number;
155	  bandwidthTB: number;
156	  phpVersions: string;
157	}): HostingPlanLimits {
158	  const php = String(plan.phpVersions ?? "")
159	    .split(",")
160	    .map((v) => v.trim())
161	    .filter((v) => /^\d\.\d$/.test(v));
162	  return {
163	    diskGB: Math.max(1, Math.floor(plan.diskGB || 1)),
164	    maxSites: Math.max(1, Math.floor(plan.maxSites || 1)),
165	    maxDatabases: Math.max(0, Math.floor(plan.maxDatabases || 0)),
166	    bandwidthTB: Math.max(0, plan.bandwidthTB || 0),
167	    phpVersions: php.length ? php : ["8.3"],
168	  };
169	}
170	
171	/** Disk quota in KB blocks for `setquota` (1 GB = 1,048,576 one-KB blocks). */
172	export function diskQuotaBlocks(diskGB: number): number {
173	  return Math.max(1, Math.floor(diskGB)) * 1024 * 1024;
174	}
175	
176	/**
177	 * Inode (file-count) quota for `setquota`, the containment for a DoS the block
178	 * quota alone doesn't stop: a tenant creating MILLIONS of tiny files exhausts the
179	 * shared filesystem's inode table — filling no disk blocks but breaking every
180	 * neighbour's ability to create a file. `setquota … <isoft> <ihard>` of `0 0`
181	 * means UNLIMITED inodes, so a real cap is required here. Scales gently off the
182	 * plan's disk size but is floored (a 1 GB plan still gets working room) and
183	 * ceilinged (a huge plan can't effectively uncap); hard carries 25% headroom
184	 * over soft so a tenant hits the soft warning before the hard wall.
185	 */
186	export function diskQuotaInodes(diskGB: number): { soft: number; hard: number } {
187	  const gb = Math.max(1, Math.floor(diskGB || 1));
188	  const soft = Math.min(2_000_000, Math.max(200_000, gb * 50_000));
189	  const hard = Math.floor(soft * 1.25);
190	  return { soft, hard };
191	}
192	
193	/**
194	 * What the customer sets in DNS to point a domain at their account: an A record
195	 * to the node's shared public IP. (A CNAME to the node FQDN is offered too when
196	 * the node has one, for sub-domains / apex-ALIAS providers.)
197	 */
198	export function pointToRecords(node: { publicIp: string; hostnameFqdn?: string | null }): {
199	  aRecord: string;
200	  cnameTarget: string | null;
201	} {
202	  return { aRecord: node.publicIp, cnameTarget: node.hostnameFqdn?.trim() || null };
203	}
204	
205	/** The absolute home + web root for an account's jailed user. */
206	export function accountPaths(username: string): { home: string; webroot: string; fpmPool: string } {
207	  return {
208	    home: `/home/${username}`,
209	    webroot: `/home/${username}/public_html`,
210	    fpmPool: `/etc/php/fpm-pools/${username}.conf`,
211	  };
212	}
213	
214	/**
215	 * Per-account directory holding the self-signed FALLBACK cert generated at
216	 * provision time (fullchain.pem + privkey.pem). Its whole purpose: nginx can
217	 * `listen 443 ssl` from the moment the account exists, so HTTPS shows a cert
218	 * WARNING, never ERR_CONNECTION_REFUSED — the real Let's Encrypt cert replaces it
219	 * once the SSL sweep issues one. Username is already validated before this reaches
220	 * a shell (isValidUnixUsername), same as accountPaths. */
221	export function selfSignedCertDir(username: string): string {
222	  return `/etc/ssl/hosting/${username}`;
223	}
224	
225	/**
226	 * A single DNS label for a subdomain (the part left of the primary domain, e.g.
227	 * "shop" in shop.example.com). No dots — a subdomain is exactly one label deep;
228	 * lowercase alnum + internal hyphens only, so it is shell-inert AND a valid
229	 * hostname label + directory name.
230	 */
231	const SUB_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/;
232	export function isValidSubdomainLabel(label: string): boolean {
233	  return SUB_LABEL_RE.test(String(label ?? "").trim().toLowerCase());
234	}
235	
236	/**
237	 * A hard-to-guess token for the Adminer DB-manager directory dropped inside an
238	 * account's webroot (`/nxtools-<token>/adminer.php`). Lowercase alnum only, so it
239	 * is shell-inert AND a valid nginx-served directory name; length-bounded to keep
240	 * it unguessable without being unwieldy. The real access control is the tenant's
241	 * scoped DB login, not the token — this just keeps the path off casual discovery.
242	 */
243	const DBTOOL_TOKEN_RE = /^[a-z0-9]{16,40}$/;
244	export function isValidDbToolToken(token: string): boolean {
245	  return DBTOOL_TOKEN_RE.test(String(token ?? ""));
246	}
247	
248	/** Docroot + parent dir for a subdomain, jailed under the account home. */
249	export function subdomainPaths(username: string, label: string): { dir: string; docroot: string } {
250	  const dir = `/home/${username}/subdomains/${label}`;
251	  return { dir, docroot: `${dir}/public_html` };
252	}
253	
254	/** Docroot + parent dir for an addon domain, jailed under the account home. */
255	export function addonDomainPaths(username: string, domain: string): { dir: string; docroot: string } {
256	  const dir = `/home/${username}/domains/${domain}`;
257	  return { dir, docroot: `${dir}/public_html` };
258	}
259	
260	/**
261	 * The branded "your site is ready" page written into an EMPTY docroot at provision
262	 * time, so a freshly provisioned site (or new subdomain/addon) shows a polished Nxeon
263	 * placeholder instead of a bare nginx 403. It is only ever written when no
264	 * index.html / index.php already exists, and any real content the customer uploads
265	 * (or a WordPress/app install's index.php) supersedes it — nginx's `index index.php
266	 * index.html` order means an installed app wins automatically.
267	 *
268	 * Self-contained: inline CSS, system-font stack, no external assets (the box has no
269	 * asset-fetch guarantee and external fonts may be blocked). `domain` is only ever a
270	 * validated hostname ([a-z0-9.-]) so it is safe to interpolate into the markup, and
271	 * the string is written via a QUOTED heredoc so the shell never interprets it.
272	 */
273	export function hostingParkingPage(domain: string): string {
274	  const host = String(domain ?? "").trim() || "your site";
275	  return `<!doctype html>
276	<html lang="en">
277	<head>
278	<meta charset="utf-8">
279	<meta name="viewport" content="width=device-width, initial-scale=1">
280	<meta name="robots" content="noindex">
281	<title>${host} — coming soon</title>
282	<style>
283	  :root { color-scheme: dark; }
284	  * { box-sizing: border-box; margin: 0; padding: 0; }
285	  body {
286	    min-height: 100vh; display: grid; place-items: center; padding: 24px;
287	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
288	    color: #e8ecf5; background: #070b18;
289	    background-image:
290	      radial-gradient(60rem 60rem at 15% -10%, rgba(124,92,255,0.18), transparent 60%),
291	      radial-gradient(50rem 50rem at 110% 10%, rgba(34,211,238,0.14), transparent 55%);
292	  }
293	  .card {
294	    width: 100%; max-width: 560px; text-align: center;
295	    padding: 48px 40px; border-radius: 20px;
296	    background: rgba(17,24,42,0.72);
297	    border: 1px solid rgba(255,255,255,0.08);
298	    box-shadow: 0 30px 80px -30px rgba(0,0,0,0.8);
299	    backdrop-filter: blur(8px);
300	  }
301	  .badge {
302	    display: inline-flex; align-items: center; gap: 8px;
303	    font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase;
304	    color: #a9b6d6; padding: 6px 12px; border-radius: 999px;
305	    border: 1px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.03);
306	  }
307	  .dot { width: 8px; height: 8px; border-radius: 50%; background: #34d399; box-shadow: 0 0 12px #34d399; }
308	  h1 { font-size: 30px; line-height: 1.15; margin: 22px 0 10px; font-weight: 700; letter-spacing: -0.02em; }
309	  .domain {
310	    background: linear-gradient(90deg, #a78bfa, #22d3ee);
311	    -webkit-background-clip: text; background-clip: text; color: transparent;
312	    word-break: break-all;
313	  }
314	  p { color: #aab3c9; font-size: 15px; line-height: 1.6; margin: 0 auto; max-width: 42ch; }
315	  .steps { list-style: none; margin: 26px 0 0; display: grid; gap: 10px; text-align: left; }
316	  .steps li {
317	    display: flex; gap: 12px; align-items: flex-start;
318	    font-size: 14px; color: #c6cee0; padding: 12px 14px;
319	    border: 1px solid rgba(255,255,255,0.07); border-radius: 12px; background: rgba(255,255,255,0.02);
320	  }
321	  .steps b { color: #fff; font-weight: 600; }
322	  .n { flex: none; width: 22px; height: 22px; border-radius: 7px; display: grid; place-items: center;
323	       font-size: 12px; font-weight: 700; color: #070b18; background: linear-gradient(135deg, #a78bfa, #22d3ee); }
324	  footer { margin-top: 28px; font-size: 12px; color: #6b7590; }
325	  footer a { color: #9fb0d6; text-decoration: none; }
326	</style>
327	</head>
328	<body>
329	  <main class="card">
330	    <span class="badge"><span class="dot"></span>Site is live</span>
331	    <h1>Your website is ready<br><span class="domain">${host}</span></h1>
332	    <p>This is a temporary placeholder. Your hosting is active — add your site and this page disappears automatically.</p>
333	    <ol class="steps">
334	      <li><span class="n">1</span><span><b>Install an app</b> — one-click WordPress and more from your Nxeon dashboard.</span></li>
335	      <li><span class="n">2</span><span><b>Or upload your files</b> — connect over SFTP or the file manager and drop them in <b>public_html</b>.</span></li>
336	      <li><span class="n">3</span><span><b>Point your domain</b> — add a real domain and free SSL from the dashboard.</span></li>
337	    </ol>
338	    <footer>Powered by <a href="https://nxeon.cloud">Nxeon</a></footer>
339	  </main>
340	</body>
341	</html>
342	`;
343	}
344	
345	/**
346	 * True for a well-formed 5-field cron schedule ("m h dom mon dow"). Each field is
347	 * restricted to the digits/ranges/steps/lists/`*` cron uses — nothing that could
348	 * be a shell metacharacter — so the schedule is safe to write into a crontab.
349	 * (Named shortcuts like @daily are intentionally NOT accepted here.)
350	 */
351	const CRON_FIELD_RE = /^[0-9*/,\-]+$/;
352	export function isValidCronSchedule(schedule: string): boolean {
353	  const parts = String(schedule ?? "").trim().split(/\s+/);
354	  if (parts.length !== 5) return false;
355	  return parts.every((p) => p.length > 0 && p.length <= 40 && CRON_FIELD_RE.test(p));
356	}
357	
358	/**
359	 * True for a cron command safe to place in a crontab line. It runs AS the jailed
360	 * user (crontab -u <user>), so it is already confined; the only invariants we
361	 * enforce here protect our own crontab writer: no newlines (one line per job) and
362	 * no `%` (cron's literal-newline metacharacter), and a sane length.
363	 */
364	export function isValidCronCommand(command: string): boolean {
365	  const c = String(command ?? "");
366	  if (c.length < 1 || c.length > 500) return false;
367	  return !/[\n\r%]/.test(c);
368	}
369	
370	/* ------------------------------------------------------------------------- *
371	 * Provisioner hardening (config generators for NEW accounts)
372	 *
373	 * These are the security-critical config the provisioner writes onto a
374	 * MULTI-TENANT box. They are pure + unit-tested here because a subtle gap in
375	 * any of them (a missing dangerous PHP function, a world-readable webroot, an
376	 * un-escaped GRANT wildcard) is not one customer's bug — it is a cross-tenant
377	 * breach. worker/hosting.ts imports these; it never re-derives them inline.
378	 * ------------------------------------------------------------------------- */
379	
380	/**
381	 * PHP functions blocked in every account's FPM pool (`disable_functions`).
382	 *
383	 * On a shared box `disable_functions` is a real isolation control, not defence
384	 * in depth: without it a tenant's PHP can shell out (`exec`/`system`), fork out
385	 * of `open_basedir` (`pcntl_exec` — compiled into PHP, so it bypasses a naive
386	 * blocklist), rewrite its own env (`putenv` → `LD_PRELOAD`/`GCONV_PATH`
387	 * tricks), plant symlinks that escape the jail (`symlink`/`link`), or reach the
388	 * host via `ffi`/`dl`. Everything a tenant could use to break out of its pool
389	 * belongs here. Kept sorted-by-purpose + deduped.
390	 */
391	export const PHP_DISABLED_FUNCTIONS: readonly string[] = [
392	  // Command execution — the classic RCE surface.
393	  "exec", "passthru", "shell_exec", "system", "proc_open", "popen",
394	  // Process control — pcntl_exec is compiled in and bypasses the above blocklist;
395	  // fork/signal/proc_nice let a tenant escape open_basedir or starve neighbours.
396	  "pcntl_exec", "pcntl_fork", "pcntl_signal", "proc_nice",
397	  // Environment + dynamic loading — putenv enables LD_PRELOAD-style escapes,
398	  // dl/ffi load native code straight past the PHP sandbox.
399	  "putenv", "dl", "ffi",
400	  // Filesystem jail-breaks — symlink/link can point out of open_basedir.
401	  "symlink", "link",
402	  // Mail — a shared box is a prized spam relay. mail() is blocked; mb_send_mail
403	  // is an equivalent wrapper, and imap_open/imap_mail can send too — block all.
404	  "mail", "mb_send_mail", "imap_open", "imap_mail",
405	  // Misc host-reach / info-leak vectors.
406	  "error_log", "curl_multi_exec", "parse_ini_file", "show_source",
407	] as const;
408	
409	/** The comma-separated `disable_functions` value for a pool config. */
410	export function phpDisableFunctions(): string {
411	  return [...PHP_DISABLED_FUNCTIONS].join(",");
412	}
413	
414	/**
415	 * Filesystem ownership + permission plan for a new account.
416	 *
417	 * The isolation goal: nginx (www-data) must serve a tenant's files, but a
418	 * NEIGHBOURING tenant (its own jailed unix user) must not be able to read them
419	 * — so nothing here is world-readable (the old `755` webroot let any tenant
420	 * read a peer's wp-config.php if open_basedir was ever escaped).
421	 *
422	 *  - home    `711 root:root` — chroot-safe (root-owned, no group/other write)
423	 *            and world-traversable so nginx can *reach* the webroot, but NOT
424	 *            world-listable, so a peer can't enumerate the home.
425	 *  - webroot `2750 <user>:www-data` — owner (the tenant's FPM pool) read/write,
426	 *            group www-data (nginx) read, world nothing. The setgid bit makes
427	 *            files the tenant creates inherit the www-data group so nginx keeps
428	 *            serving them; peers (neither owner nor in www-data) are shut out.
429	 *  - tmp     `700 <user>:<user>` — private PHP scratch (upload/session dir).
430	 *
431	 * nginx reaches tenant files via GROUP membership (www-data owns the webroot
432	 * group), never via world bits — that is the whole point of dropping 755.
433	 */
434	export function accountFsPlan(username: string): {
435	  home: { owner: string; mode: string };
436	  webroot: { owner: string; mode: string };
437	  tmp: { owner: string; mode: string };
438	  nginxGroup: string;
439	} {
440	  return {
441	    home: { owner: "root:root", mode: "711" },
442	    webroot: { owner: `${username}:www-data`, mode: "2750" },
443	    tmp: { owner: `${username}:${username}`, mode: "700" },
444	    nginxGroup: "www-data",
445	  };
446	}
447	
448	/** PHP-FPM pool hardening limits applied to every account pool. */
449	export const FPM_MEMORY_LIMIT = "256M";
450	export const FPM_REQUEST_TERMINATE_TIMEOUT = "120s";
451	
452	/**
453	 * The per-account PHP-FPM pool config (the PHP isolation boundary). Pure: given
454	 * the validated username + jailed paths, returns the exact pool file contents.
455	 *
456	 * open_basedir is scoped to the account home (+ the shared PHP lib) and NO
457	 * LONGER includes `/tmp`: PHP's tmp/session dirs are redirected into the home,
458	 * so a world-writable `/tmp` on open_basedir was just an unnecessary shared
459	 * surface between tenants. memory_limit + request_terminate_timeout cap a
460	 * single tenant from exhausting the shared box.
461	 */
462	export function fpmPoolConfig(username: string, home: string, webroot: string): string {
463	  const sock = `/run/php/${username}.sock`;
464	  return [
465	    `[${username}]`,
466	    `user = ${username}`,
467	    `group = ${username}`,
468	    `listen = ${sock}`,
469	    `listen.owner = ${username}`,
470	    `listen.group = www-data`,
471	    `pm = ondemand`,
472	    `pm.max_children = 6`,
473	    `pm.process_idle_timeout = 30s`,
474	    `chdir = ${webroot}`,
475	    // TRAILING SLASHES are load-bearing: `${home}` (no slash) would also authorise
476	    // `${home}2/…` — a sibling tenant's home — so open_basedir must pin the prefix
477	    // to the directory itself via the trailing `/` (same for the shared PHP lib).
478	    `php_admin_value[open_basedir] = ${home}/:/usr/share/php/`,
479	    `php_admin_value[disable_functions] = ${phpDisableFunctions()}`,
480	    `php_admin_value[memory_limit] = ${FPM_MEMORY_LIMIT}`,
481	    `php_admin_value[request_terminate_timeout] = ${FPM_REQUEST_TERMINATE_TIMEOUT}`,
482	    `php_admin_value[upload_tmp_dir] = ${home}/tmp`,
483	    `php_admin_value[session.save_path] = ${home}/tmp`,
484	  ].join("\n");
485	}
