487	/**
488	 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
489	 *
490	 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
491	 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
492	 * tenant's database. Escaping them (and the escape char itself) with a
493	 * backslash pins the grant to exactly one database.
494	 */
495	export function escapeGrantDbName(name: string): string {
496	  return name.replace(/([\\_%])/g, "\\$1");
497	}
498	
499	/**
500	 * The scoped SQL that creates one account database + user and grants that user
501	 * privileges on THAT DATABASE ONLY.
502	 *
503	 * Security invariants (audited): the GRANT is pinned to the exact db via
504	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
505	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
506	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
507	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
508	 */
509	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
510	  const grantName = escapeGrantDbName(dbName);
511	  return (
512	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
513	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
514	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
515	    `FLUSH PRIVILEGES;`
516	  );
517	}
518	
519	// ---- Proprietary in-portal DB manager (Nxeon-built, replaces Adminer) -------
520	
521	/** The account-level MySQL user the in-portal DB manager authenticates as. One
522	 *  per account, derived from the (already shell/SQL-safe) username. Kept <=32
523	 *  chars — MySQL's user-name limit. Usernames are `[a-z][a-z0-9]{2,31}` (no
524	 *  underscore), so `<username>_mgr` is unambiguous and never collides with a
525	 *  per-database user (`<username>_<slug>`) whose slug can't be the reserved
526	 *  literal `mgr` used here… — we simply reserve this name for the manager. */
527	export function dbMgrUserFor(username: string): string {
528	  return `${username}_mgr`.slice(0, 32);
529	}
530	
531	/** Is this a syntactically valid MySQL account/database identifier for OUR
532	 *  generated names? Deliberately strict — only the charset our provisioner ever
533	 *  produces (`<username>_<slug>` / `<username>_mgr`), so a value that reaches the
534	 *  `mysql` command line as a flag can carry no shell metacharacters. NOT for
535	 *  arbitrary user-supplied table names (those are validated by membership against
536	 *  SHOW TABLES + backtick-quoting, never interpolated into a shell). */
537	const DB_IDENT_RE = /^[a-z0-9_]{1,64}$/;
538	export function isValidDbIdentifier(name: string): boolean {
539	  return DB_IDENT_RE.test(String(name ?? ""));
540	}
541	
542	/**
543	 * The grant that scopes the DB-manager user to EXACTLY this account's own
544	 * databases and nothing else. The privilege target is `<username>\_%`.* — the
545	 * account username, a LITERAL underscore (escaped so it is not a LIKE wildcard),
546	 * then `%`. That matches every `<username>_<...>` database the account can create
547	 * and, because usernames are `[a-z][a-z0-9]{2,31}` (never contain `_`), can never
548	 * match another tenant's `<otheruser>_<...>` databases — the same escaped-glob
549	 * boundary the backup/terminate paths already rely on.
550	 *
551	 * Security invariants (mirror buildScopedGrantSql): the grant is db-scoped, never
552	 * `*.*`, so `ALL PRIVILEGES` here confers NO server-level FILE/PROCESS/SUPER — the
553	 * manager user therefore cannot read files (LOAD_FILE/INTO OUTFILE), see other
554	 * connections, or touch the `mysql`/system schemas. Returns plain SQL with real
555	 * backticks; the caller shell-escapes for `mysql -e`.
556	 */
557	export function buildDbMgrGrantSql(username: string, mgrUser: string, mgrPass: string): string {
558	  // `${username}\_%` — escape only the underscore (username itself is [a-z0-9]).
559	  const scope = `${username}\\_%`;
560	  return (
561	    `CREATE USER IF NOT EXISTS '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
562	    `ALTER USER '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
563	    `GRANT ALL PRIVILEGES ON \`${scope}\`.* TO '${mgrUser}'@'localhost'; ` +
564	    `FLUSH PRIVILEGES;`
565	  );
566	}
