85	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
86	function strongPassword(len = 22): string {
87	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
88	  const bytes = randomBytes(len);
89	  let out = "";
90	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
91	  return out;
92	}
