94	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
95	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
96	  if (!password) throw new Error("Hosting node has no root credential on record.");
97	  const conn = new Client();
98	  await new Promise<void>((resolve, reject) => {
99	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
100	    conn
101	      .on("ready", () => { clearTimeout(timer); resolve(); })
102	      .on("error", (e) => { clearTimeout(timer); reject(e); })
103	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
104	  });
105	  return conn;
106	}
107	
108	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
109	  return new Promise((resolve, reject) => {
110	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
111	    conn.exec(command, (err, stream) => {
112	      if (err) { clearTimeout(timer); return reject(err); }
113	      let out = "";
114	      stream
115	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
116	        .on("data", (d: Buffer) => { out += d.toString(); })
117	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
118	    });
119	  });
120	}
121	
122	async function run(conn: Client, label: string, cmd: string): Promise<void> {
123	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
124	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
125	}
