127	/** True when a non-empty file exists at `path` on the node (`test -s`). Used to
128	 *  gate real-cert vhosts on the cert actually being present, so nginx -t never
129	 *  fails on a missing ssl_certificate. `path` is only ever an internally-built
130	 *  /etc/letsencrypt path, never tenant input. */
131	async function fileExistsOnNode(conn: Client, path: string): Promise<boolean> {
132	  const r = await exec(conn, `test -s ${path} && echo yes || echo no`);
133	  return r.out.trim() === "yes";
134	}
