395	async function provisionHostingDatabase(dbId: string): Promise<void> {
396	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
397	  if (!rec || rec.status !== "PENDING") return;
398	  if (SANDBOX || !ENABLED) {
399	    // KEEP the encrypted password (no longer nulled) so it stays viewable from the
400	    // panel in sandbox/dev and remains available once shared hosting is enabled.
401	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", error: SANDBOX ? null : "Shared hosting not enabled." } });
402	    return;
403	  }
404	  const name = rec.name;
405	  const user = rec.dbUser;
406	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
407	  // DB name + user were built from the validated username; re-assert shape.
408	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
409	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
410	    return;
411	  }
412	  try {
413	    const conn = await connectNode(rec.account.node);
414	    try {
415	      // Grants scoped to THIS database only — the data-isolation boundary.
416	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
417	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
418	      await run(conn, "create database", `mysql -e "${sql}"`);
419	    } finally {
420	      try { conn.end(); } catch { /* */ }
421	    }
422	    // KEEP the encrypted password on the row (no longer nulled) so the customer can
423	    // view it later from the Databases panel (revealHostingDbPassword). It was
424	    // stored encrypted at creation and never leaves the server except via the
425	    // owner-checked reveal action.
426	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", error: null } });
427	  } catch (e) {
428	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
429	  }
430	}
