592	/**
593	 * Extra server_name ALIASES the account's PRIMARY vhost must keep serving: every
594	 * PRIMARY-kind hostname claim OTHER than the current primaryDomain. Normally empty
595	 * (an account has exactly one PRIMARY claim = its own domain) → the primary vhost is
596	 * rendered exactly as before. After taskSetPrimaryDomain promotes an addon, the OLD
597	 * primary is retained as a second PRIMARY claim and surfaces here, so every later
598	 * reinstall of the primary vhost (SSL sweep, health self-heal) keeps the old address
599	 * alive instead of silently dropping it on the next cert reissue.
600	 */
601	async function primaryAliasesFor(accountId: string, primaryDomain: string): Promise<string[]> {
602	  const cur = normalizeClaimHostname(primaryDomain);
603	  const claims = await db.hostingHostnameClaim
604	    .findMany({ where: { accountId, kind: "PRIMARY" }, select: { hostname: true } })
605	    .catch(() => [] as { hostname: string }[]);
606	  return claims.map((c) => c.hostname).filter((h) => h && h !== cur && isValidHostingDomain(h));
607	}
