609	/**
610	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
611	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
612	 * block. Safe: touches only nginx + certbot, never sshd.
613	 */
614	export async function hostingSslSweep(): Promise<void> {
615	  if (SANDBOX || !ENABLED) return;
616	  const accts = await db.hostingAccount.findMany({
617	    where: { status: "ACTIVE", sslActive: false },
618	    include: { node: true },
619	    take: 20,
620	  });
621	  for (const a of accts) {
622	    try {
623	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
624	      const d = a.primaryDomain;
625	      // FREE SUBDOMAIN + wildcard enabled: the ONE `*.<base>` wildcard already covers
626	      // it, so NEVER issue a per-domain LE cert (slow + burns the ~50/week quota).
627	      // Just fold the account onto the wildcard vhost (real HTTPS) once the cert is
628	      // present on the node, and mark it live. Flag off ⇒ this branch is skipped ⇒
629	      // the per-domain flow below runs exactly as before.
630	      if (hostingWildcardEnabled() && isFreeSubdomain(d)) {
631	        if (!wildcardCoversHost(d)) continue; // not a single-label child of base — nothing to do
632	        const wild = wildcardCertLiveDir();
633	        const conn = await connectNode(a.node);
634	        try {
635	          if (!(await fileExistsOnNode(conn, `${wild}/fullchain.pem`))) continue; // wildcard not minted yet
636	          const { webroot } = accountPaths(a.username);
637	          await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: wild, real: true }));
638	        } finally {
639	          try { conn.end(); } catch { /* */ }
640	        }
641	        await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
642	        console.log(`[hosting] wildcard HTTPS active for ${d}`);
643	        continue;
644	      }
645	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
646	      // Any alias domains the primary vhost must keep (e.g. the old address after a
647	      // set-primary promotion). Fold them into the cert (--allow-subset-of-names keeps
648	      // the issue succeeding for the primary even if an alias can't validate) AND the
649	      // reinstalled vhost's server_name, so a reissue never drops the old address.
650	      const aliases = await primaryAliasesFor(a.id, d);
651	      const conn = await connectNode(a.node);
652	      try {
653	        const dflags = [d, `www.${d}`, ...aliases.flatMap((al) => [al, `www.${al}`])].map((n) => `-d ${n}`).join(" ");
654	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html ${dflags} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
655	        const liveDir = `/etc/letsencrypt/live/${d}`;
656	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
657	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
658	        const { webroot } = accountPaths(a.username);
659	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: liveDir, real: true }, aliases));
660	      } finally {
661	        try { conn.end(); } catch { /* */ }
662	      }
663	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
664	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
665	    } catch (e) {
666	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
667	    }
668	  }
669	
670	  // Addon domains get their own per-domain cert the same way, once they resolve
671	  // to the node's shared IP. (Subdomains are folded into the account cert below.)
672	  const addons = await db.hostingAddonDomain.findMany({
673	    where: { status: "ACTIVE", sslActive: false },
674	    include: { account: { include: { node: true } } },
675	    take: 20,
676	  });
677	  for (const ad of addons) {
678	    try {
679	      const u = ad.account.username;
680	      const d = ad.domain;
681	      if (!isValidHostingDomain(d) || !isValidUnixUsername(u)) continue;
682	      if (!(await domainPointsAt(d, ad.account.node.publicIp))) continue; // DNS not pointed yet
683	      const conn = await connectNode(ad.account.node);
684	      try {
685	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
686	        const liveDir = `/etc/letsencrypt/live/${d}`;
687	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
688	        if (have.out.trim() !== "yes") { console.log(`[hosting] addon cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
689	        const { docroot } = addonDomainPaths(u, d);
690	        await installNamedVhost(conn, `${u}-${d}`, renderSiteVhost(`${d} www.${d}`, docroot, `/run/php/${u}.sock`, liveDir));
691	      } finally {
692	        try { conn.end(); } catch { /* */ }
693	      }
694	      await db.hostingAddonDomain.update({ where: { id: ad.id }, data: { sslActive: true } });
695	      console.log(`[hosting] HTTPS active for addon ${d}`);
696	    } catch (e) {
697	      console.error(`[hosting] addon ssl sweep ${ad.id} failed`, e);
698	    }
699	  }
700	
701	  // Subdomains: fold each into its ACCOUNT'S existing Let's Encrypt cert as an
702	  // extra SAN once it resolves to the node, then serve 443 for it off that same
703	  // live dir. We reuse the account cert (HTTP-01 webroot, --expand) rather than a
704	  // wildcard: a wildcard needs DNS-01 + a DNS-provider API we don't hold (customers
705	  // self-manage their DNS), whereas SAN expansion works off the pointed A record —
706	  // the same flow every other cert here uses. The subdomain's HTTP vhost already
707	  // proxies /.well-known/acme-challenge to /var/www/html, so the challenge serves.
708	  const pendingSubs = await db.hostingSubdomain.findMany({
709	    where: { status: "ACTIVE", sslActive: false },
710	    include: { account: { include: { node: true } } },
711	    take: 30,
712	  });
713	  // One reissue per account per sweep even if several of its subdomains are pending
714	  // — the reissue covers them all at once, and each is verified independently below.
715	  const seenAccounts = new Set<string>();
716	  for (const sub of pendingSubs) {
717	    if (seenAccounts.has(sub.accountId)) continue;
718	    seenAccounts.add(sub.accountId);
719	    try {
720	      const a = sub.account;
721	      const u = a.username;
722	      const primary = a.primaryDomain;
723	      if (!isValidHostingDomain(primary) || !isValidUnixUsername(u)) continue;
724	      // Free-subdomain accounts are covered by the node's `*.<base>` wildcard, and
725	      // this account has NO per-domain LE cert (the primary sweep no longer mints one
726	      // for them). Their sub-labels are two levels under the base — the single-label
727	      // wildcard can't cover them and the `*.<base>` A record doesn't resolve them —
728	      // so an --expand reissue here would only burn LE quota. Skip entirely when the
729	      // wildcard is enabled; flag off ⇒ the SAN-expansion flow below runs as before.
730	      if (hostingWildcardEnabled() && isFreeSubdomain(primary)) continue;
731	      const liveDir = `/etc/letsencrypt/live/${primary}`;
732	      // All ACTIVE subdomains of this account, and which of them already resolve to
733	      // us. Only names that resolve are folded in, so certbot never churns on a name
