89	export type QueryResult = {
90	  columns: string[];
91	  rows: string[][];
92	  /** true when we stopped at MAX_OUTPUT_BYTES / the row cap and more data exists. */
93	  truncated: boolean;
94	  /** non-null on a MySQL/transport error (already trimmed for display). */
95	  error: string | null;
96	  /** ms the query took end-to-end (for the UI). */
97	  elapsedMs: number;
98	};
