111	/** Open a direct-tcpip channel from the root SSH connection to the node's
112	 *  localhost MySQL. The returned Channel is a duplex stream we hand to mysql2 as
113	 *  its socket — MySQL stays bound to localhost on the node (never exposed). */
114	function forwardMysqlChannel(conn: Client): Promise<ClientChannel> {
115	  return new Promise<ClientChannel>((resolve, reject) => {
116	    const timer = setTimeout(() => reject(new Error("SSH tunnel to MySQL timed out")), CONNECT_TIMEOUT_MS);
117	    conn.forwardOut("127.0.0.1", 0, "127.0.0.1", 3306, (err, channel) => {
118	      clearTimeout(timer);
119	      if (err) return reject(err);
120	      resolve(channel);
121	    });
122	  });
123	}
