895	/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
896	 *  when curl couldn't get a response (connection refused/timeout → "000"). */
897	function parseHttpCode(out: string): number {
898	  const n = parseInt(out.trim().slice(-3), 10);
899	  return Number.isFinite(n) ? n : 0;
900	}
901	/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
902	 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
903	 *  (we never mark an account falsely healthy). */
904	function servesOk(code: number): boolean {
905	  return code >= 200 && code < 400;
906	}
907	
908	/**
909	 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
910	 * curls http/https for each account's own Host header and records whether nginx
911	 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
912	 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
913	 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
914	 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
915	 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
916	 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
917	 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
918	 * ~10-min tick. Returns the number of accounts processed.
919	 */
920	export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
921	  const onlyRequested = opts.onlyRequested === true;
922	  if (SANDBOX) {
923	    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
924	    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
925	    const accts = await db.hostingAccount.findMany({
926	      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
927	      select: { id: true, sslActive: true },
928	      take: onlyRequested ? 25 : 50,
929	    });
930	    for (const a of accts) {
931	      await db.hostingAccount.update({
932	        where: { id: a.id },
933	        data: {
934	          serveHttpOk: true,
935	          serveHttpsOk: true,
936	          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
937	          healthCheckedAt: new Date(),
938	          recheckRequested: false,
939	        },
940	      }).catch(() => undefined);
941	    }
942	    return accts.length;
943	  }
944	  if (!ENABLED) return 0;
945	
946	  const accts = await db.hostingAccount.findMany({
947	    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
948	    include: { node: true },
949	    // Newest-requested first so a customer who just clicked "Check now" is served
950	    // before the routine backlog even in the full sweep.
951	    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
952	    take: onlyRequested ? 25 : 30,
953	  });
954	  let processed = 0;
955	  for (const a of accts) {
956	    try {
957	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
958	      const d = a.primaryDomain;
959	      const u = a.username;
960	      let serveHttpOk = false;
961	      let serveHttpsOk = false;
962	      let sslActive = a.sslActive;
963	      let note = "";
964	      const conn = await connectNode(a.node);
965	      try {
966	        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
967	        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
968	        serveHttpOk = servesOk(parseHttpCode(httpR.out));
969	        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));
970	
971	        // Does a REAL Let's Encrypt cert exist on the node for this domain?
972	        const liveDir = `/etc/letsencrypt/live/${d}`;
973	        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
974	
975	        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
976	        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
977	        // re-verify. This is the recovery from exactly the state kaymo hit.
978	        if (haveReal && !serveHttpsOk) {
