985	            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
986	            serveHttpsOk = servesOk(parseHttpCode(reR.out));
987	            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
988	          } catch (e) {
989	            note = "HTTPS repair failed — support notified";
990	            console.error(`[hosting] health self-heal ${a.id} failed`, e);
991	          }
992	        }
993	        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live
994	
995	        if (!note) {
