1009	        where: { id: a.id },
1010	        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
1011	      });
1012	      processed++;
1013	    } catch (e) {
1014	      console.error(`[hosting] health sweep ${a.id} failed`, e);
1015	      // Clear the recheck flag even on failure so a broken node can't wedge the
