1087	  // ownership was mixed — which is how a deleted account kept serving (2026-08-21).
1088	  // The explicit `rm -rf` is the backstop that guarantees the docroot is gone. The
1089	  // username is validated by assertLifecycleSafe() above, so the path is safe.
1090	  await run(conn, "terminate: delete user + home", `pkill -u ${a.username} 2>/dev/null; sleep 1; userdel -r ${a.username} 2>/dev/null || true; rm -rf /home/${a.username} 2>/dev/null || true`);
