1106	/**
1107	 * Resolve the install TARGET carried in a WORDPRESS_INSTALL / APP_INSTALL payload
1108	 * to a concrete docroot + hostname on the node. Back-compat: when no target is
1109	 * present (or `kind === "primary"`), the account's primary webroot + primaryDomain
1110	 * are used exactly as before. For a subdomain/addon target the row is looked up
1111	 * SCOPED TO THE ACCOUNT (the cross-tenant guard — the worker never trusts a raw
1112	 * docroot from the payload) and must be ACTIVE; every shell-bound part is
1113	 * re-validated here before it can reach a command.
1114	 */
1115	async function resolveInstallTarget(
1116	  a: { id: string; username: string; primaryDomain: string },
1117	  payload: string | null,
1118	): Promise<{ docroot: string; hostname: string }> {
1119	  const u = a.username;
1120	  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
1121	  let target: { kind?: string; id?: string } = {};
1122	  try {
1123	    target = (JSON.parse(payload || "{}").target ?? {}) as { kind?: string; id?: string };
1124	  } catch {
1125	    target = {};
1126	  }
1127	  const kind = String(target.kind ?? "primary");
1128	  const id = String(target.id ?? "");
1129	
1130	  if (kind === "subdomain" && id) {
1131	    const sub = await db.hostingSubdomain.findFirst({ where: { id, accountId: a.id } });
1132	    if (!sub || sub.status !== "ACTIVE") throw new Error("target subdomain not found or not active");
1133	    if (!isValidSubdomainLabel(sub.label)) throw new Error("unsafe subdomain label");
1134	    const fqdn = `${sub.label}.${a.primaryDomain}`;
1135	    if (!isValidHostingDomain(fqdn)) throw new Error("unsafe subdomain hostname");
1136	    return { docroot: subdomainPaths(u, sub.label).docroot, hostname: fqdn };
1137	  }
1138	  if (kind === "addon" && id) {
1139	    const addon = await db.hostingAddonDomain.findFirst({ where: { id, accountId: a.id } });
1140	    if (!addon || addon.status !== "ACTIVE") throw new Error("target addon domain not found or not active");
1141	    if (!isValidHostingDomain(addon.domain)) throw new Error("unsafe addon domain");
1142	    return { docroot: addonDomainPaths(u, addon.domain).docroot, hostname: addon.domain };
1143	  }
1144	  // Default / primary.
1145	  if (!isValidHostingDomain(a.primaryDomain)) throw new Error("unsafe account");
1146	  return { docroot: accountPaths(u).webroot, hostname: a.primaryDomain };
1147	}
