1152	  const dbName = String(p.dbName ?? "");
1153	  const dbUser = String(p.dbUser ?? "");
1154	  const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
1155	  const adminUser = String(p.adminUser ?? "");
1156	  const adminPass = (p.adminPassEnc ? decryptSecret(p.adminPassEnc) : "") ?? "";
1157	  const adminEmail = String(p.adminEmail ?? "");
1158	  if (!SAFE_ID.test(dbName) || !SAFE_ID.test(dbUser.slice(0, 32)) || !/^[A-Za-z0-9]{1,64}$/.test(dbPass)) throw new Error("invalid db identifiers");
1159	  if (!/^[A-Za-z0-9_]{1,32}$/.test(adminUser) || !/^[A-Za-z0-9]{8,64}$/.test(adminPass) || !SAFE_EMAIL.test(adminEmail)) throw new Error("invalid admin identifiers");
