1165	
1166	  await run(conn, "wp-cli", `command -v wp >/dev/null 2>&1 || (curl -fsSL https://raw.githubusercontent.com/wp-cli/builds/gh-pages/phar/wp-cli.phar -o /usr/local/bin/wp && chmod +x /usr/local/bin/wp)`);
1167	  const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
1168	  await run(conn, "wp db", `mysql -e "${sql}"`);
1169	  const wp = `sudo -u ${u} -H wp --path=${docroot}`;
1170	  await run(conn, "wp download", `${wp} core download --force`);
1171	  await run(conn, "wp config", `${wp} config create --dbname=${dbName} --dbuser=${dbUser} --dbpass='${dbPass}' --force`);
1172	  await run(conn, "wp install", `${wp} core install --url='https://${d}' --title='${d}' --admin_user='${adminUser}' --admin_password='${adminPass}' --admin_email='${adminEmail}' --skip-email`);
