1248	/** Archive the account's home + DB dumps to a node-local backups dir.
1249	 *
1250	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
1251	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
1252	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
1253	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
1254	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
1255	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
1256	 * dumps root-owned and off the tenant tree means the archived SQL is always our
1257	 * own mysqldump output, never tenant-controlled. */
1258	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
1259	  const u = a.username;
1260	  const dir = `/var/hosting-backups/${u}`;
1261	  const dumpDir = `${dir}/dbdump`;
1262	  const path = `${dir}/${tsLabel}.tar.gz`;
1263	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
1264	  // tenant can neither read nor tamper with it.
1265	  await run(
1266	    conn,
1267	    "dump dbs",
1268	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
1269	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
1270	  );
1271	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
1272	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
1273	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
1274	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
1275	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
1276	  // Retain the newest 5 per account; delete older files + rows.
1277	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
1278	  for (const old of all.slice(5)) {
1279	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
1280	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
1281	  }
1282	}
