1288	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
1289	 * database, and the SQL content is our own dump, not anything the tenant could
1290	 * have planted (see taskBackup). */
1291	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
1292	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
1293	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
1294	  if (!b) throw new Error("backup not found");
1295	  const u = a.username;
1296	  const { home, webroot } = accountPaths(u);
1297	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
1298	  const stage = `/var/hosting-backups/${u}/.restore`;
1299	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
1300	  // Files: the archive root holds ${u}/… — copy it back over the home.

1300	  // Files: the archive root holds ${u}/… — copy it back over the home.
1301	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
1302	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
1303	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
1304	  // another tenant's DB is never fed to mysql.
1305	  await run(
1306	    conn,
1307	    "restore dbs",
1308	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
1309	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
1310	  );
