1315	    conn,
1316	    "fix perms",
1317	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
1318	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
