1514	  await run(
1515	    conn,
1516	    "install adminer",
1517	    `sudo -u ${u} -H bash -c "mkdir -p ${webroot}/${dir} && curl -fsSL '${ADMINER_URL}' -o ${webroot}/${dir}/adminer.php"`,
1518	  );
1519	  await db.hostingAccount.update({ where: { id: a.id }, data: { dbToolPath: urlPath } });
