1523	/**
1524	 * Provision (or repair) the account-level scoped MySQL user for the PROPRIETARY
1525	 * in-portal DB manager. Creates `<username>_mgr`@'localhost' and grants it on
1526	 * `<username>\_%`.* ONLY — every one of THIS account's databases and nothing else
1527	 * (see buildDbMgrGrantSql for the escaped-glob isolation proof). The password was
1528	 * generated + stored encrypted by ensureDbManager; we decrypt it here to apply
1529	 * it. Idempotent (CREATE USER IF NOT EXISTS + ALTER USER re-asserts the password,
1530	 * so a repair run realigns the box with the stored cred). Flips dbMgrReady=true
1531	 * so the portal can start executing queries as this user.
1532	 *
1533	 * SECURITY: the grant is db-scoped, so `ALL PRIVILEGES` confers NO global
1534	 * FILE/PROCESS/SUPER — this user can never read node files or reach a peer's
1535	 * databases or the `mysql`/system schemas. The SQL is built from validated
1536	 * identifiers and a `[A-Za-z0-9]` password, shell-escaped for `mysql -e` exactly
1537	 * like the per-database create.
1538	 */
1539	async function taskEnsureDbMgr(conn: Client, a: { id: string; username: string; dbMgrUser: string | null; dbMgrPassEnc: string | null }): Promise<void> {
