1545	    throw new Error("invalid db-manager credential");
1546	  }
1547	  const sql = sqlForMysqlExec(buildDbMgrGrantSql(u, mgrUser, pass));
1548	  await run(conn, "ensure db-manager user", `mysql -e "${sql}"`);
1549	  await db.hostingAccount.update({ where: { id: a.id }, data: { dbMgrUser: mgrUser, dbMgrReady: true } });
