1571	/**
1572	 * Promote an ACTIVE addon domain to the account's PRIMARY domain.
1573	 *
1574	 * The account's MAIN website (its `public_html`, reached until now at the old
1575	 * primary address) starts answering on the new domain, and the OLD primary is kept
1576	 * as an ALIAS server_name so its address keeps working. Order is chosen so the old
1577	 * address NEVER stops serving:
1578	 *   1. Regenerate the primary vhost `hosting-<user>.conf` with the new domain as
1579	 *      server_name + the old domain as an alias (nginx -t guarded). We pick a cert
1580	 *      dir that is GUARANTEED to exist — the real Let's Encrypt cert for the new
1581	 *      domain if the addon already had one, else the account's self-signed fallback
1582	 *      — so `nginx -t` can't fail on a missing cert and 443 keeps listening.
1583	 *   2. Remove the addon's OWN vhost (it now conflicts with the primary's
1584	 *      server_name). The addon docroot files are LEFT on disk (data retention).
1585	 *   3. If WordPress lives in the primary docroot, rewrite its stored URLs.
1586	 * Only after every node step succeeds do we flip DB `primaryDomain`, delete the
1587	 * addon row and re-key the hostname claim (new → PRIMARY; old stays claimed as the
1588	 * alias). On any failure we throw BEFORE the DB flip, so the account keeps its old
1589	 * primary domain and — because the primary vhost already carries the old name as an
1590	 * alias — the old address keeps serving. `sslActive` is reset unless a real cert for
1591	 * the new domain is already live, so the SSL sweep issues/verifies one.
1592	 */
1593	async function taskSetPrimaryDomain(
1594	  conn: Client,
1595	  a: { id: string; username: string; primaryDomain: string },
1596	  payload: string | null,
1597	): Promise<string> {
1598	  const addonId = String(JSON.parse(payload || "{}").addonId ?? "");
1599	  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId: a.id } });
1600	  if (!addon) throw new Error("addon domain not found");
1601	  if (addon.status !== "ACTIVE") throw new Error("the domain is still being set up");
1602	  const u = a.username;
1603	  const newDomain = addon.domain;
1604	  const oldDomain = a.primaryDomain;
1605	  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
1606	  if (!isValidHostingDomain(newDomain)) throw new Error("unsafe new primary domain");
1607	  if (!isValidHostingDomain(oldDomain)) throw new Error("unsafe old primary domain");
1608	  if (newDomain === oldDomain) {
1609	    // Already the primary (defensive) — just clean up the addon bookkeeping.
1610	    await db.hostingAddonDomain.delete({ where: { id: addon.id } }).catch(() => undefined);
1611	    return JSON.stringify({ note: `${newDomain} is already your primary domain.` });
1612	  }
1613	  const { webroot } = accountPaths(u);
1614	  const sock = `/run/php/${u}.sock`;
1615	
1616	  // Pick a cert dir that DEFINITELY exists so `nginx -t` can never fail on it.
1617	  const realLive = `/etc/letsencrypt/live/${newDomain}`;
1618	  const haveReal = (await exec(conn, `test -s ${realLive}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
1619	  const certDir = haveReal ? realLive : selfSignedCertDir(u);
1620	
1621	  // 1. Repoint the primary vhost: new domain as server_name, old kept as an alias.
1622	  await installVhost(conn, u, renderHostingVhost(u, newDomain, webroot, sock, { certDir, real: haveReal }, [oldDomain]));
1623	  // 2. Drop the addon's own vhost (its server_name now belongs to the primary). Keep
1624	  //    its docroot files on disk.
1625	  await removeNamedVhost(conn, `${u}-${newDomain}`);
1626	  // 3. WordPress URL rewrite, when the PRIMARY docroot actually runs WordPress.
1627	  const isWp = (await exec(conn, `sudo -u ${u} -H wp --path=${webroot} core is-installed >/dev/null 2>&1 && echo yes || echo no`)).out.trim() === "yes";
1628	  if (isWp) {
1629	    const wp = `sudo -u ${u} -H wp --path=${webroot}`;
1630	    await run(conn, "wp search-replace", `${wp} search-replace '${oldDomain}' '${newDomain}' --all-tables --skip-columns=guid`);
1631	    await run(conn, "wp home/siteurl", `${wp} option update home 'https://${newDomain}' && ${wp} option update siteurl 'https://${newDomain}'`);
1632	  }
1633	
1634	  // Node is consistent — commit the DB flip. Re-key the hostname claim (new domain
1635	  // ADDON → PRIMARY); the old domain keeps its existing claim as the served alias.
1636	  await db.hostingAccount.update({
1637	    where: { id: a.id },
1638	    data: { primaryDomain: newDomain, sslActive: haveReal, recheckRequested: true },
1639	  });
1640	  await db.hostingHostnameClaim
1641	    .updateMany({ where: { hostname: normalizeClaimHostname(newDomain) }, data: { kind: "PRIMARY" } })
1642	    .catch(() => undefined);
1643	  await db.hostingAddonDomain.delete({ where: { id: addon.id } }).catch(() => undefined);
1644	  return JSON.stringify({ note: `Primary domain is now ${newDomain}. ${oldDomain} still works.`, url: `https://${newDomain}/` });
1645	}
