110	async function hostingChargeCents(
111	  plan: { priceCents: number },
112	  term: number,
113	  extraGB: number,
114	): Promise<{ annualPct: number; planTermCents: number; extraTermCents: number; fullCharge: number; promoCharge: number }> {
115	  const annualPct = await annualDiscountPct();
