118	  const planTermCents = termPriceCents(plan.priceCents, term, annualPct);
119	  const fullCharge = planTermCents + extraTermCents;
120	  const promoCharge = Math.max(0, planTermCents - firstMonthCreditCents(planTermCents, term)) + extraTermCents;
