163	  // OPTIONAL domain. An empty domain means "start me on a free temporary
164	  // `<username>.nxeon.cloud` subdomain, I'll connect a real domain later" — the
165	  // customer is never forced to own a domain to sign up. A REAL domain keeps every
166	  // cross-tenant guard it always had; the temp subdomain is derived from the
167	  // account's own per-node-unique username (below) so it can't collide with
168	  // anything a customer typed, and its uniqueness is still enforced by the SAME
169	  // atomic UNIQUE(hostname) claim inside the charge tx.
170	  const wantTemp = !String(domain ?? "").trim();
171	  let name = "";
172	  if (!wantTemp) {
173	    name = normalizeHostingDomain(domain);
174	    if (!name) return { error: "Enter a domain." };
175	    if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
176	  }
177	
178	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
179	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
