181	  if (!wantTemp) {
182	    // One account per domain across ALL customers — same cross-tenant guard as
183	    // email subscriptions (a shared vhost keys on server_name).
184	    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
185	    if (dupe) {
186	      return {
187	        error:
188	          dupe.userId === user.id
189	            ? "You already have a hosting account for this domain."
190	            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
191	      };
192	    }
193	    // Also reject if this hostname is already someone's subdomain or addon domain
