226	  }
227	  // Pricing (annual rate + extra-disk rate resolved once, frozen onto the account,
228	  // read back at renewal — displayed === charged === renewed). Shared with the
229	  // card-split pre-check in `placeHostingOrder` via `hostingChargeCents` so the amount
230	  // the card leg is computed from and the amount debited here can never use different
231	  // formulas.
232	  const { annualPct, planTermCents, extraTermCents, fullCharge, promoCharge } = await hostingChargeCents(plan, term, extraGB);
233	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
234	  const anticipated = eligible ? promoCharge : fullCharge;
235	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
236	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
237	  // Free temporary subdomain: derived from the just-allocated (per-node-unique)
238	  // username, validated the same way a real domain is and de-duplicated by the same
239	  // atomic hostname claim inside the tx. The advisory pre-check here is friendly UX
240	  // only — a collision across nodes is caught authoritatively by UNIQUE(hostname).
241	  if (wantTemp) {
242	    // A customer-CHOSEN free subdomain (`<label>.<base>`) if they picked one in the
243	    // wizard, else the auto-derived `<username>.<base>`. Either way it lives under our
244	    // `*.<HOSTING_SUBDOMAIN_BASE>` wildcard, so it resolves + gets HTTPS automatically
245	    // (no A record for the customer to set). The chosen label is validated here and
246	    // de-duplicated by the SAME atomic UNIQUE(hostname) claim inside the charge tx —
247	    // the wizard's live availability check (checkHostingSubdomain) is advisory UX only.
248	    const label = String(subdomainLabelRaw ?? "").trim().toLowerCase();
249	    if (label) {
250	      if (!isValidSubdomainLabel(label)) {
251	        return { error: "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
252	      }
253	      name = freeSubdomainFor(label);
254	      if (!isValidHostingDomain(name)) return { error: "That subdomain isn’t a valid hostname — try a different one." };
255	      if (await isHostnameClaimed(name)) {
256	        return { error: `${name} is already taken — please choose another subdomain.` };
257	      }
258	    } else {
259	      name = tempSubdomainFor(username);
260	      if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
261	      if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
262	    }
263	  }
264	
265	  let accountId = "";
266	  // Captured out of the charge tx for the post-commit invoice document (Fix A). TS
267	  // control-flow can't see the assignment inside the async callback, so seed it.
268	  let debitedCents = 0;
269	  try {
270	    await db.$transaction(async (tx) => {
271	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
272	      let debitCents = fullCharge;
273	      let promoClaimId: string | null = null;
274	      // MONEY BUG FIX (2026-08-12): gate the claim on `eligible`, NOT `promoEnabled`.
275	      // claimFirstMonthFree INSERTs a redemption row and catches the P2002 unique
276	      // violation ("already redeemed") to return {claimed:false}. But Postgres POISONS
277	      // the whole transaction the instant any statement fails — a caught error does
278	      // NOT un-abort it — so the very next statement (debitWallet's updateMany) then
279	      // dies with 25P02 ("current transaction is aborted"). Result: EVERY repeat
280	      // customer who already used the free month could no longer place a hosting order
281	      // (the order failed, wallet never charged). `eligible` is the same authoritative
282	      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
283	      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
284	      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
285	      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
286	      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
287	      // full. So exactly one free month is ever granted.
288	      if (eligible) {
289	        const claim = await claimFirstMonthFree(tx, {
290	          userId: user.id,
291	          ipHash,
292	          serviceType: "HOSTING",
293	          campaign,
294	          chargedCents: promoCharge,
295	        });
296	        if (claim.claimed) {
297	          debitCents = promoCharge;
298	          promoClaimId = claim.id;
299	        }
300	      }
301	      const note = (debitCents < fullCharge ? " — First month free" : "") + (extraGB > 0 ? ` + ${extraGB} GB storage` : "");
302	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
303	      // so the customer sees the yearly commitment AND its real per-month rate. Uses the
304	      // PLAN per-month rate (the add-on has its own $/GB/mo shown in the storage note).
305	      const effMonthly = term > 1 ? Math.round(planTermCents / term) : 0;
306	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
307	      await debitWallet(tx, user.id, debitCents);
308	      debitedCents = debitCents;
309	      await tx.walletTransaction.create({
310	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
311	      });
312	      const acct = await tx.hostingAccount.create({
313	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
314	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
315	        // (identical at runtime then — see lib/order.ts's Server create).
316	        data: {
317	          userId: user.id,
318	          hostingNodeId: node.id,
319	          planId: plan.id,
320	          username,
321	          primaryDomain: name,
322	          status: "PENDING",
323	          // Quota already folds in the purchased extra disk, so the node's setquota
324	          // (applyIsolation → taskApplyPlanLimits) provisions the right size with no
325	          // add-on awareness of its own.
326	          diskQuotaMB: effectiveDiskGB(limits.diskGB, extraGB) * 1024,
327	          extraDiskGB: extraGB,
328	          maxSites: limits.maxSites,
329	          maxDatabases: limits.maxDatabases,
330	          // The term this account was SOLD on, and the annual rate frozen at sale, so
331	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
332	          termMonths: term,
333	          annualDiscountPct: annualPct,
334	          expiresAt: addMonths(new Date(), term),
335	        } as Prisma.HostingAccountUncheckedCreateInput,
336	      });
337	      accountId = acct.id;
338	      // Atomic hostname claim in the SAME tx as the account row. A colliding
339	      // primaryDomain (another order, or someone's subdomain/addon of the same
340	      // name racing us past the advisory isHostnameClaimed check) fails here on
341	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
342	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
343	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
344	    });
345	  } catch (e) {
346	    if (isUniqueViolation(e)) {
347	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
348	    }
349	    // The generic message below is intentionally opaque to the customer, but the
350	    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
351	    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
352	    // table missing because a `prisma db push` didn't apply → the INSERT throws
353	    // here). Log it before swallowing. No money-logic change — the tx already rolled
354	    // back, so the wallet was NOT charged.
355	    console.error("[hosting.order] failed", {
356	      userId: user.id,
357	      planId,
358	      domain: name,
359	      code: (e as { code?: string })?.code,
360	      err: e instanceof Error ? e.message : e,
361	    });
362	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
363	  }
364	
365	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
366	
367	  // Fix A — the itemised invoice DOCUMENT + its emailed PDF for a hosting order.
368	  // Fires here in the CORE placement fn, so it runs exactly once for BOTH the
369	  // wallet path (orderHostingAccount) and the card path (fulfilCheckoutSession →
370	  // placeHostingOrderCore → here). Post-commit and fully best-effort: the wallet has
371	  // already been debited, so a mail/invoice failure must NEVER surface as an order
372	  // failure. This is a separate record from the wallet-credit top-up receipt a card
373	  // order gets from lib/stripe.ts. Hosting is untaxed, so the amount is the real
374	  // debited cents (0 on a granted first-month-free — a legitimate $0 record).
375	  try {
376	    const invTermLabel = vpsTerm(term).label;
377	    const invDesc = `Web Hosting: ${plan.name} for ${name} — ${invTermLabel}`;
378	    const createdInvoice = await db.invoice.create({
379	      data: invoiceCreateData({
380	        userId: user.id,
381	        description: invDesc,
382	        status: "PAID",
383	        taxCents: 0,
384	        taxRatePercent: 0,
385	        taxCountry: null,
386	        period: { start: new Date(), end: addMonths(new Date(), term) },
387	        lineItems: [{ description: invDesc, qty: 1, unitCents: debitedCents, amountCents: debitedCents }],
388	      }),
389	    });
390	    const { sendMail, emails } = await import("./mailer");
391	    const branding = await invoiceBranding();
392	    const tpl = emails.invoiceNew(
393	      {
394	        invoiceNumber: formatInvoiceNumber(createdInvoice.number, branding.numberPrefix),
395	        amount: `$${(createdInvoice.amountCents / 100).toFixed(2)}`,
396	        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
397	        description: invDesc,
398	      },
399	      true, // the itemised PDF is attached (invoiceId passed below)
400	    );
401	    await sendMail({
402	      to: user.email,
403	      subject: tpl.subject,
404	      html: tpl.html,
405	      template: tpl.template,
406	      invoiceId: createdInvoice.id,
407	      userId: user.id,
408	      kind: "invoice",
409	    });
410	  } catch {
411	    /* invoice + email is best-effort — a placed order must never fail on it */
412	  }
413	
414	  revalidatePath("/dashboard/hosting");
415	  return { ok: true, accountId };
416	}
