418	// ---------- Checkout wizard (payment-method-captured order) ------------------
419	//
420	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
421	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
422	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
423	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
424	// REFUSES to provision unless the account has a way to bill the renewal (a saved
425	// card OR a wallet balance that already covers one renewal), it is idempotent
426	// against double-submit, and it then delegates the ACTUAL charge to the audited
427	// `orderHostingAccount` above — one debit path, never a second one.
428	//
429	// displayed === charged === renewed: this action computes NO price of its own for
430	// the debit. The wallet debit + the first-month-free reserve→confirm→release
431	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
432	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
433	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
434	
435	export type HostingOrderInput = {
436	  planId: string;
437	  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
438	  domain?: string;
439	  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
440	  subdomainLabel?: string;
441	  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
442	  extraDiskGB?: number;
443	  termMonths?: number;
444	  /** Optional catalog app to auto-install after the account provisions. */
445	  appSlug?: string;
446	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
447	  idempotencyKey: string;
448	  /**
449	   * "Apply my balance" — mirrors the VPS wizard toggle. Defaults ON (only an explicit
450	   * `false` turns it off) so every existing caller keeps applying the wallet first.
451	   * When the balance doesn't fully cover the amount due today — because the toggle is
452	   * off, or the balance is short — the remainder is charged to a card (funding the
453	   * wallet), exactly like VPS.
454	   */
455	  useWallet?: boolean;
456	};
457	
458	export type HostingOrderResult =
459	  | { ok: true; accountId: string }
460	  | { error: string }
461	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
462	  | { needCard: true; renewalCents: number }
463	  /** A card leg is due: mount this embedded Stripe checkout; fulfilment places the order. */
464	  | { checkout: EmbeddedCheckout };
465	
466	/**
467	 * The full-price single renewal of a plan/term — the gate threshold, identical to
468	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
469	 */
470	async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
471	  const annualPct = await annualDiscountPct();
472	  const perGbCents = await extraDiskPerGbCents();
473	  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
474	}
475	
476	/** Place a hosting order from the checkout wizard. See the block comment above. */
477	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
478	  const user = await requireUser();
479	  await assertNotImpersonating();
480	  const unverified = await emailVerificationError(user);
481	  if (unverified) return { error: unverified };
482	
483	  const key = String(input.idempotencyKey ?? "").trim();
484	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
485	
486	  const term = normalizeProductTerm(input.termMonths);
487	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
488	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
489	
490	  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
491	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
492	
493	  // WALLET/CARD SPLIT — the money-path fork mirroring VPS `payAndDeploy`. The amount
494	  // due TODAY (after any first-month-free credit) is split against the balance and the
495	  // "apply my balance" toggle; `useWallet` defaults ON so the existing behaviour is
496	  // unchanged. This computes the SAME anticipated dueToday `orderHostingAccountFor`
497	  // charges (shared `hostingChargeCents`), so the card leg is a real part of the same
498	  // total, never a second price.
499	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
500	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
501	  const { fullCharge, promoCharge } = await hostingChargeCents(plan, term, extraGB);
502	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
503	  const dueTodayCents = eligible ? promoCharge : fullCharge;
504	  const useWallet = input.useWallet !== false;
505	  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet });
506	
507	  if (cardCents > 0) {
508	    // A card leg is due (the toggle is off, or the balance is short). Fund it by card
509	    // — the card is saved via `setup_future_usage`, which is ALSO the renewal method
510	    // the gate below requires, so there is no `needCard` on this path. On payment,
511	    // `fulfilCheckoutSession` credits the card amount to the wallet and calls
512	    // `placeHostingOrderCore` with these SAME inputs (and the same `hostorder:<key>`
513	    // idempotency), which debits the real charge — one debit path, unchanged.
514	    const checkout = await createHostingOrderCheckout(user, cardCents, {
515	      planId: input.planId,
516	      domain: input.domain,
517	      subdomainLabel: input.subdomainLabel,
518	      extraDiskGB: extraGB || undefined,
519	      termMonths: term,
520	      appSlug: input.appSlug,
521	      idempotencyKey: key,
522	    });
523	    if (!checkout) return { error: "Card payments aren’t set up yet — top up your wallet to deploy." };
524	    return { checkout };
525	  }
526	
527	  // cardCents <= 0 → the wallet covers the amount due today (or it is $0). EXISTING
528	  // wallet path, byte-for-byte — including the RENEWAL-METHOD GATE: never provision a
529	  // paid product with no way to bill the renewal. A saved card OR a wallet already
530	  // holding one renewal's worth qualifies; otherwise the wizard captures a card (which
531	  // also handles the $0-today first-month-free case).
532	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
533	    return { needCard: true, renewalCents };
534	  }
535	  return placeHostingOrderCore(user, input, key, term, plan, extraGB, renewalCents);
536	}
