538	/**
539	 * The idempotent placement + post-order bookkeeping, WITHOUT the auth/pricing/split
540	 * preamble — takes the loaded `user` explicitly so BOTH the interactive action
541	 * (`placeHostingOrder`, wallet path) and the card-funded fulfilment path
542	 * (`fulfilCheckoutSession`) drive the SAME `hostorder:<key>` idempotency claim and the
543	 * SAME audited `orderHostingAccountFor` debit. On the card path the wallet was already
544	 * topped up by `creditCheckoutSession` before this runs.
545	 */
546	async function placeHostingOrderCore(
547	  user: User,
548	  input: HostingOrderInput,
549	  key: string,
550	  term: number,
551	  plan: { maxDatabases: number },
552	  extraGB: number,
553	  renewalCents: number,
554	): Promise<HostingOrderResult> {
555	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
556	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
557	  // token table. A rapid resubmit or a network retry with the same key can't create
558	  // a second account or take a second debit.
559	  const sessionKey = `hostorder:${key}`;
560	  try {
561	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
562	  } catch (e) {
563	    if (isUniqueViolation(e)) {
564	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
565	      // A completed prior attempt: replay its result (no second charge).
566	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
567	      // A failed prior attempt: clear it so an explicit retry can proceed.
568	      if (prior?.status === "FAILED") {
569	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
570	      } else {
571	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
572	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
573	      }
574	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
575	      try {
576	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
577	      } catch {
578	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
579	      }
580	    } else {
581	      throw e;
582	    }
583	  }
584	
585	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
586	  // the free temporary subdomain. All money movement, the first-month-free atomic
587	  // claim and the hostname claim happen inside orderHostingAccountFor's transaction.
588	  const res = await orderHostingAccountFor(user, input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB);
589	  if (res.error || !res.accountId) {
590	    await db.fulfilledSession
591	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
592	      .catch(() => {});
593	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
594	  }
595	  await db.fulfilledSession
596	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
597	    .catch(() => {});
598	
599	  // Deploy-funnel COMPLETION — hosting's authoritative, server-side bottom of the
600	  // funnel, the counterpart to placeOrder / placeGameOrder. Hosting does NOT flow
601	  // through the shared Stripe fulfilment bus (lib/fulfil-checkout.ts has no hosting
602	  // kind — a $0 first month captures a card in `mode:"setup"`, and the charge is the
603	  // wallet debit inside orderHostingAccount), so THIS is its shared success path.
604	  // Recorded here (not on the idempotent-replay early return above) so a retry never
605	  // double-counts. Replaces the client-side trackDeployComplete removed from
606	  // HostingDeployWizard, keeping all three products on one authoritative userId-keyed
607	  // completion. Best-effort + double-guarded so it can never disturb the placed order.
608	  try {
609	    await recordDeployFunnelComplete({ product: "hosting", step: "Complete", stepIndex: 7, userId: user.id });
610	  } catch {
611	    /* never let funnel bookkeeping affect a completed order */
612	  }
613	
614	  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
615	  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
616	  // side), so an ad blocker / privacy browser silently drops it and the campaign
617	  // never learns the signup happened. Firing it here too — with the SAME event_id
618	  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
619	  // conversion when the pixel DOES load, and still counts it when the pixel is
620	  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
621	  // Best-effort: sendMetaConversion never throws, and this runs after the order is
622	  // already committed, so tracking can never affect the charge.
623	  try {
624	    const [h, ck] = await Promise.all([headers(), cookies()]);
625	    await sendMetaConversion({
626	      eventName: "Subscribe",
627	      eventId: key,
628	      email: user.email,
629	      externalId: user.id,
630	      value: renewalCents / 100,
631	      currency: "USD",
632	      clientIp: clientIp(h),
633	      userAgent: h.get("user-agent") ?? undefined,
634	      // The Meta click/browser cookies are the strongest match signals for an
635	      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
636	      // Quality well above the email/IP-only baseline. Absent for organic visits.
637	      fbc: ck.get("_fbc")?.value || undefined,
638	      fbp: ck.get("_fbp")?.value || undefined,
639	      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
640	    });
641	  } catch {
642	    /* tracking is best-effort — the order is already placed and charged */
643	  }
644	
645	  // Optional one-click app install: queue it now so the worker installs it the
646	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
647	  // the (already-charged) order; the customer can install from the panel later.
648	  const slug = String(input.appSlug ?? "").trim();
649	  if (slug) {
650	    try {
651	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
652	    } catch {
653	      /* non-fatal: the account is created and charged; the app can be installed later */
654	    }
655	  }
656	
657	  revalidatePath("/dashboard/hosting");
658	  return { ok: true, accountId: res.accountId };
659	}
