661	/**
662	 * Fulfil a CARD-funded hosting order from its PAID Stripe session. Safe to expose as a
663	 * server action: it trusts NOTHING from its caller but a Stripe session id, which it
664	 * re-retrieves and re-classifies server-side — a forged or foreign id classifies as
665	 * anything-but-hostOrder and returns a no-op, so no one can place an order billed to
666	 * another account. Called ONLY by lib/fulfil-checkout.ts (the shared webhook+redirect
667	 * bus) AFTER it has credited the card leg to the wallet; this then runs the SAME
668	 * `placeHostingOrderCore` the wallet path uses (same `hostorder:<key>` idempotency),
669	 * so the wallet is debited exactly once and a webhook + redirect can never place two
670	 * accounts. `orderHostingAccountFor`'s own first-month-free atomic claim still decides
671	 * the final price here, exactly as on the wallet path.
672	 */
673	export async function placeHostingCardOrder(
674	  sessionId: string,
675	): Promise<HostingOrderResult | { skip: true }> {
676	  const purpose = await getCheckoutPurpose(sessionId);
677	  if (purpose.kind !== "hostOrder") return { skip: true };
678	  const user = await db.user.findUnique({ where: { id: purpose.userId } });
679	  if (!user) return { error: "user not found for paid hosting order" };
680	  const intent = purpose.intent;
681	  const term = normalizeProductTerm(intent.termMonths);
682	  const plan = await db.hostingPlan.findUnique({ where: { id: intent.planId } });
683	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
684	  const extraGB = normalizeExtraDiskAddGB(intent.extraDiskGB);
685	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
686	  const input: HostingOrderInput = {
687	    planId: intent.planId,
688	    domain: intent.domain,
689	    subdomainLabel: intent.subdomainLabel,
690	    extraDiskGB: intent.extraDiskGB,
691	    termMonths: intent.termMonths,
692	    appSlug: intent.appSlug,
693	    idempotencyKey: intent.idempotencyKey,
694	    useWallet: true,
695	  };
696	  return placeHostingOrderCore(user, input, intent.idempotencyKey, term, plan, extraGB, renewalCents);
