724	/**
725	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
726	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
727	 * after provisioning. Generates DB credentials up front for apps that need one.
728	 */
729	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
730	  // WordPress is NOT an APP_RECIPES download — it installs via its own fully-
731	  // automated WORDPRESS_INSTALL task (WP-CLI). Route the wizard's one-click
732	  // WordPress here so it queues the right task with the same credential payload
733	  // installWordPress builds (mirrors that path). Any other slug must be a known
734	  // recipe app; an unknown slug is dropped (best-effort — never voids the order).
735	  if (slug === "wordpress") {
736	    if (maxDatabases < 1) return; // WordPress needs a database — no budget, skip rather than fail
737	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
738	    if (!acct) return;
739	    const dbName = `${acct.username}_wp`.slice(0, 64);
740	    const dbUser = dbName.slice(0, 32);
741	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
742	    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
743	    await db.hostingTask.create({
744	      data: {
745	        accountId,
746	        kind: "WORDPRESS_INSTALL",
747	        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
748	      },
749	    });
750	    return;
751	  }
752	  const app = hostingAppCatalog().find((x) => x.slug === slug);
753	  if (!app) return;
754	  let payload: Record<string, unknown> = { slug };
755	  if (app.needsDb) {
756	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
757	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
758	    if (!acct) return;
759	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
760	    const dbUser = dbName.slice(0, 32);
761	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
762	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
763	  }
764	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
765	}
