922	/** Create a scoped database for an account (within the plan's maxDatabases). */
923	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
924	  const user = await requireUser();
925	  await assertNotImpersonating();
926	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
927	  if (!a) return { error: "Account not found." };
928	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
929	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
930	  // A short, safe suffix keyed off the account username: <user>_<slug>.
931	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
932	  const name = `${a.username}_${slug}`.slice(0, 64);
933	  const dbUser = name.slice(0, 32);
934	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
935	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
936	  // Count + create in ONE serializable transaction, so concurrent creates can't
937	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
938	  try {
939	    await db.$transaction(async (tx) => {
940	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
941	      if (n >= a.maxDatabases) throw new Error("CAP");
942	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
943	    }, { isolationLevel: "Serializable" });
944	  } catch (e) {
945	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
946	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
947	    return { error: "A database with that name already exists, or the request raced — try again." };
948	  }
949	  revalidatePath("/dashboard/hosting");
950	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
951	  return { ok: true, password };
952	}
