1017	 * Install the per-account Adminer database manager (or return the existing one).
1018	 * Owner-or-admin + not-impersonating (same discipline as every resource-creating
1019	 * action). Queues an INSTALL_DBTOOL task that drops Adminer into THIS account's
1020	 * webroot at a randomized path served by the account's own FPM socket. The
1021	 * customer logs in with their own SCOPED DB user, so a leaked path grants no
1022	 * cross-tenant access (see the worker handler's SECURITY note). Idempotent: if the
1023	 * tool is already installed, returns its path without re-queuing.
1024	 */
1025	export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
1026	  const user = await requireUser();
1027	  await assertNotImpersonating();
1028	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, dbToolPath: true } });
1029	  if (!a) return { error: "Account not found." };
1030	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
1031	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
1032	  if (a.dbToolPath) return { ok: true, url: a.dbToolPath };
1033	  // Don't queue a second install while one is already in flight.
1034	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "INSTALL_DBTOOL", status: { in: ["PENDING", "RUNNING"] } } });
1035	  if (inFlight) return { ok: true };
1036	  const token = randomBytes(16).toString("hex").slice(0, 32); // 32 lowercase hex chars
1037	  if (!isValidDbToolToken(token)) return { error: "Couldn’t start the install — try again." };
1038	  const path = `/nxtools-${token}/adminer.php`;
1039	  await db.hostingTask.create({ data: { accountId, kind: "INSTALL_DBTOOL", payload: JSON.stringify({ token, path }) } });
1040	  revalidatePath(`/dashboard/hosting/${accountId}`);
1041	  return { ok: true };
