1055	/** Recent panel tasks for an account (so the UI can show progress + one-time results). */
1056	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
1057	  const user = await requireUser();
1058	  // A DONE task result can carry a one-time secret (the WordPress admin password);
1059	  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
1060	  await assertNotImpersonating();
1061	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
1062	  if (!a) return [];
1063	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
1064	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
1065	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
1066	  // then clear it so it isn't shown again on the next poll.
1067	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
1068	  // A DONE result may carry a one-time note; clear it after one read so it isn't
1069	  // re-shown on every poll — EXCEPT an app-install's admin login, which the customer
1070	  // needs long-term (WordPress passwords aren't recoverable). Those persist and are
1071	  // surfaced in the Overview's App Credentials panel (getHostingAppCredentials).
1072	  const toClear = rows.filter(
1073	    (t) => t.status === "DONE" && t.result && t.kind !== "WORDPRESS_INSTALL" && t.kind !== "APP_INSTALL",
1074	  );
1075	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
1076	  return out;
1077	}
