1137	/**
1138	 * Validate an install target against an account (cross-tenant guard at the action
1139	 * layer, mirrored again in the worker). For a subdomain/addon the row must exist,
1140	 * belong to THIS account, and be ACTIVE. Returns the JSON `target` to embed in the
1141	 * task payload (undefined for primary → the worker's back-compat default) plus a
1142	 * short, DB-safe suffix that keeps each site's generated database name distinct.
1143	 */
1144	async function validateSiteTarget(
1145	  accountId: string,
1146	  target: SiteTarget | undefined,
1147	): Promise<{ error?: string; payloadTarget?: { kind: string; id: string }; dbSuffix: string }> {
1148	  const kind = target?.kind ?? "primary";
1149	  if (kind === "primary") return { dbSuffix: "" };
1150	  const id = "id" in (target ?? {}) ? String((target as { id: string }).id) : "";
1151	  if (!id) return { error: "Choose a website to install onto.", dbSuffix: "" };
1152	  if (kind === "subdomain") {
1153	    const sub = await db.hostingSubdomain.findFirst({ where: { id, accountId }, select: { status: true } });
1154	    if (!sub) return { error: "That subdomain isn’t part of this account.", dbSuffix: "" };
1155	    if (sub.status !== "ACTIVE") return { error: "That subdomain is still being set up.", dbSuffix: "" };
1156	    return { payloadTarget: { kind: "subdomain", id }, dbSuffix: randomBytes(3).toString("hex") };
1157	  }
1158	  if (kind === "addon") {
1159	    const addon = await db.hostingAddonDomain.findFirst({ where: { id, accountId }, select: { status: true } });
1160	    if (!addon) return { error: "That domain isn’t part of this account.", dbSuffix: "" };
1161	    if (addon.status !== "ACTIVE") return { error: "That domain is still being set up.", dbSuffix: "" };
1162	    return { payloadTarget: { kind: "addon", id }, dbSuffix: randomBytes(3).toString("hex") };
1163	  }
1164	  return { error: "Unknown install target.", dbSuffix: "" };
1165	}
