1167	export async function installWordPress(accountId: string, target?: SiteTarget): Promise<HostingResult> {
1168	  const ctx = await ownedActiveAccount(accountId);
1169	  if ("error" in ctx) return { error: ctx.error };
1170	  const { user, a } = ctx;
1171	  if (a._count.databases >= a.maxDatabases) return { error: `WordPress needs a database, but your plan's ${a.maxDatabases} are used. Delete one first.` };
1172	  const tgt = await validateSiteTarget(accountId, target);
1173	  if (tgt.error) return { error: tgt.error };
1174	  // Generate all creds up front; the worker applies them, then the admin login is
1175	  // returned ONCE via the task result. A per-site suffix keeps each site's DB name
1176	  // unique (primary keeps the legacy `<user>_wp` name for back-compat).
1177	  const dbName = `${a.username}_wp${tgt.dbSuffix}`.slice(0, 64);
1178	  const dbUser = dbName.slice(0, 32);
1179	  const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
1180	  const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
1181	  await db.hostingTask.create({
1182	    data: {
1183	      accountId,
1184	      kind: "WORDPRESS_INSTALL",
1185	      payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: user.email, ...(tgt.payloadTarget ? { target: tgt.payloadTarget } : {}) }),
1186	    },
1187	  });
