1252	export async function listHostingUpgradePlans(accountId: string): Promise<{ currentPlanName?: string; plans?: UpgradePlanView[]; error?: string }> {
1253	  const user = await requireUser();
1254	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
1255	  if (!a) return { error: "Account not found." };
1256	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
1257	  const cur = a.plan;
1258	  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
1259	  const plans = all
1260	    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
1261	    .map((p) => ({
1262	      id: p.id, name: p.name, priceCents: p.priceCents, diskGB: p.diskGB, maxSites: p.maxSites,
1263	      maxDatabases: p.maxDatabases, bandwidthTB: p.bandwidthTB, tagline: p.tagline,
