1269	/**
1270	 * Move a hosting account UP to a larger plan. Same purchase discipline as
1271	 * orderHostingAccount: no spending while impersonating, wallet charge in the same
1272	 * tx that mutates the account.
1273	 *
1274	 * Billing choice (kept simple + honest): we charge the FULL per-term price
1275	 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
1276	 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
1277	 * the flow one debit and never owes the customer money back. The customer sees the
1278	 * exact delta before confirming. Only UP is allowed (a downgrade would need a
1279	 * refund path we don't have).
1280	 */
1281	export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
1282	  const user = await requireUser();
1283	  await assertNotImpersonating();
1284	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
1285	  if (!a) return { error: "Account not found." };
1286	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
1287	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
1288	  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
1289	  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
1290	  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
1291	  const cur = a.plan;
1292	  // Up-only guard (re-checked server-side; never trust the client's picker).
1293	  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
1294	    return { error: "You can only move to a larger plan." };
1295	  }
1296	  const limits = planLimits(newPlan);
1297	  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
1298	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
1299	
1300	  try {
1301	    await db.$transaction(async (tx) => {
1302	      if (chargeCents > 0) {
1303	        await debitWallet(tx, user.id, chargeCents);
1304	        await tx.walletTransaction.create({
1305	          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
1306	        });
1307	      }
1308	      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
1309	      // does at creation), so a later plan edit can't silently re-quota this account.
1310	      // phpVersion is left as-is: an upgrade only widens the allowed set.
1311	      await tx.hostingAccount.update({
1312	        where: { id: a.id },
1313	        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
1314	      });
1315	      // Enact the node-level change (raise disk quota + rewrite FPM pool).
1316	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
1317	    });
1318	  } catch (e) {
1319	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
1320	    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
1321	  }
1322	
1323	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
1324	  revalidatePath(`/dashboard/hosting/${accountId}`);
1325	  return { ok: true };
1326	}
