1421	  // Impersonating admins must not create/destroy customer resources — cron is
1422	  // arbitrary command execution as the customer's unix user; subdomains/addons
1423	  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
1424	  await assertNotImpersonating();
1425	  const a = await db.hostingAccount.findUnique({
1426	    where: { id },
1427	    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
1428	  });
1429	  if (!a) return { error: "Account not found." as const };
1430	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
1431	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
