1435	/**
1436	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
1437	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
1438	 * subdomain, or an addon domain. Before this, each creator only checked its own
1439	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
1440	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
1441	 *
1442	 * This is now a FAST, FRIENDLY PRE-CHECK only — good UX (an early, clear error)
1443	 * but NOT trusted alone: a non-atomic read can't stop two concurrent requests
1444	 * from both passing it and both committing the same server_name (the co-tenant
1445	 * vhost-shadowing TOCTOU). The authoritative guard is the atomic UNIQUE(hostname)
1446	 * insert into HostingHostnameClaim done INSIDE each creator's transaction — a
1447	 * colliding claim fails there (P2002) and rolls the whole tx back.
1448	 */
1449	async function isHostnameClaimed(name: string): Promise<boolean> {
1450	  // The authoritative registry (single UNIQUE(hostname) spanning all three kinds)
1451	  // is the fast, definitive pre-check now. We also still scan the three resource
1452	  // tables so any legacy row created before the claims table existed is honoured.
1453	  const host = normalizeClaimHostname(name);
1454	  const [claim, prim, sub, addon] = await Promise.all([
1455	    db.hostingHostnameClaim.count({ where: { hostname: host } }),
1456	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
1457	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
1458	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
1459	  ]);
1460	  return claim + prim + sub + addon > 0;
1461	}
