1463	/** True when an error is a Prisma unique-constraint violation (P2002). A colliding
1464	 *  hostname claim surfaces here — the atomic guard that replaces trusting the read. */
1465	function isUniqueViolation(e: unknown): boolean {
1466	  return (e as { code?: string })?.code === "P2002";
1467	}
