1552	export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
1553	  const ctx = await ownedSiteAccount(accountId);
1554	  if ("error" in ctx) return { error: ctx.error };
1555	  const { a } = ctx;
1556	  const name = normalizeHostingDomain(domain);
1557	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
1558	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
1559	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
1560	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
1561	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
1562	  if (await isHostnameClaimed(name)) {
1563	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
1564	  }
1565	  const { docroot } = addonDomainPaths(a.username, name);
1566	  try {
1567	    await db.$transaction(async (tx) => {
1568	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1569	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1570	      if (subs + addons >= a.maxSites) throw new Error("CAP");
1571	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
1572	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) is the
1573	      // authoritative guard against another tenant committing this same
1574	      // server_name as their primary/subdomain/addon between our check and commit.
1575	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: a.id, kind: "ADDON" } });
1576	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
