1579	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
1580	    if (isUniqueViolation(e)) return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
1581	    return { error: "That domain is already added, or the request raced — try again." };
1582	  }
1583	  revalidatePath(`/dashboard/hosting/${accountId}`);
1584	  return { ok: true };
1585	}
