1637	    db.hostingSubdomain.findMany({ where: { accountId, status: { not: "DELETING" } }, orderBy: { createdAt: "asc" } }),
1638	    db.hostingAddonDomain.findMany({ where: { accountId, status: { not: "DELETING" } }, orderBy: { createdAt: "asc" } }),
1639	    db.hostingTask.findMany({
1640	      where: { accountId, status: "DONE", kind: { in: ["WORDPRESS_INSTALL", "APP_INSTALL"] } },
