1708	/**
1709	 * Promote an ACTIVE addon domain to the account's PRIMARY domain. Owner or admin,
1710	 * never while impersonating (same discipline as every resource-mutating action).
1711	 * The DB `primaryDomain` is NOT flipped here — the worker (taskSetPrimaryDomain)
1712	 * flips it only after the node vhost + WordPress URL rewrite succeed, keeping the
1713	 * old address serving as an alias in the meantime (worst-case safe). Idempotent
1714	 * against double-click: refuses if a promotion is already queued/running.
1715	 */
1716	export async function setPrimaryHostingDomain(accountId: string, addonId: string): Promise<HostingResult> {
1717	  const user = await requireUser();
1718	  await assertNotImpersonating();
1719	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, primaryDomain: true } });
1720	  if (!a) return { error: "Account not found." };
1721	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
1722	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
1723	  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId }, select: { id: true, domain: true, status: true } });
1724	  if (!addon) return { error: "That domain isn’t part of this account." };
1725	  if (addon.status !== "ACTIVE") return { error: "That domain is still being set up — wait until it’s live, then try again." };
1726	  if (addon.domain === a.primaryDomain) return { error: "That’s already your primary domain." };
1727	  const inFlight = await db.hostingTask.findFirst({
1728	    where: { accountId, kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"], status: { in: ["PENDING", "RUNNING"] } },
1729	  });
1730	  if (inFlight) return { error: "A primary-domain change is already in progress." };
1731	  await db.hostingTask.create({
1732	    data: {
1733	      accountId,
1734	      kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"],
1735	      payload: JSON.stringify({ addonId: addon.id, newDomain: addon.domain, oldDomain: a.primaryDomain }),
1736	    },
1737	  });
1738	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.setprimary", detail: `${a.primaryDomain} → ${addon.domain}` } }).catch(() => {});
