104	  if (!a) return { error: "Account not found." as const };
105	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
106	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
107	  return { user, a };
108	}
