122	/**
123	 * Make sure the account has a provisioned DB-manager user. Idempotent:
124	 *   - already ready → { ready:true }
125	 *   - has creds but no ACTIVE user yet (or first call) → generate creds if
126	 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
127	 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
128	 * SANDBOX: mark ready immediately (no real node).
129	 */
130	export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
131	  const ctx = await loadOwned(accountId);
132	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
133	  await assertNotImpersonating();
134	  const { a } = ctx;
135	  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };
136	
137	  if (SANDBOX) {
138	    if (!a.dbMgrReady) {
139	      await db.hostingAccount.update({
140	        where: { id: a.id },
141	        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
142	      });
143	    }
144	    return { ready: true, provisioning: false, enabled: true };
145	  }
146	
147	  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };
148	
149	  // Generate + persist the manager credential once (encrypted at rest); the
150	  // worker applies it on the node. Keep the same password across re-queues so the
151	  // stored cred always matches what the node was told.
152	  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
153	    await db.hostingAccount.update({
154	      where: { id: a.id },
155	      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
156	    });
157	  }
158	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
159	  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
160	  revalidatePath(`/dashboard/hosting/${accountId}`);
161	  return { ready: false, provisioning: true, enabled: true };
162	}
