164	export async function dbmgrStatus(accountId: string): Promise<DbMgrStatus & { error?: string }> {
165	  const ctx = await loadOwned(accountId);
166	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
167	  const { a } = ctx;
168	  if (SANDBOX) return { ready: !!a.dbMgrReady, provisioning: false, enabled: true };
169	  const provisioning = !a.dbMgrReady && !!(await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } }));
170	  return { ready: !!a.dbMgrReady, provisioning, enabled: true };
171	}
