187	const SANDBOX_TABLES = ["customers", "orders", "products"];
188	function sandboxResult(sql: string): DbMgrResult {
189	  const s = sql.trim().toLowerCase();
190	  if (s.startsWith("show tables")) {
191	    return { columns: ["Tables_in_demo"], rows: SANDBOX_TABLES.map((t) => [t]), truncated: false, error: null, elapsedMs: 3 };
192	  }
193	  if (s.startsWith("select count(")) {
194	    return { columns: ["n"], rows: [["3"]], truncated: false, error: null, elapsedMs: 2 };
195	  }
196	  if (s.startsWith("select")) {
197	    return {
198	      columns: ["id", "name", "created_at"],
199	      rows: [["1", "Ada Lovelace", "2026-01-02 10:00:00"], ["2", "Grace Hopper", "2026-01-03 11:30:00"], ["3", "Katherine Johnson", "2026-01-04 09:15:00"]],
200	      truncated: false, error: null, elapsedMs: 4,
201	    };
202	  }
203	  return { columns: [], rows: [], truncated: false, error: null, elapsedMs: 2, ok: true };
204	}
