206	/** List a database's tables (SHOW TABLES as the scoped user). Owner-or-admin +
207	 *  not-impersonating (it reaches the customer's live data). */
208	export async function dbmgrListTables(accountId: string, dbName: string): Promise<{ error?: string; tables?: string[] }> {
209	  const ctx = await loadOwned(accountId);
210	  if ("error" in ctx) return { error: ctx.error };
211	  await assertNotImpersonating();
212	  const { user } = ctx;
213	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
214	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
215	  if (SANDBOX) return { tables: SANDBOX_TABLES };
216	  const target = dbTargetFor(ctx.a);
217	  if (!target) return { error: "The database manager is still being prepared." };
218	  const res = await runScopedSql(target, dbName, showTablesSql());
219	  if (res.error) return { error: res.error };
220	  return { tables: res.rows.map((r) => r[0]).filter(Boolean) };
221	}
